/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MatDialog } from '@angular/material/dialog';
import { NEVER, of } from 'rxjs';
import { ConfirmDialogComponent } from './confirm-dialog.component';
import { ConfirmDialogService } from './confirm-dialog.service';

describe('ConfirmDialogService', () => {
  let dialog: jasmine.SpyObj<MatDialog>;
  let service: ConfirmDialogService;

  const closingWith = (value: unknown) => dialog.open.and.returnValue({ afterClosed: () => of(value) } as any);

  beforeEach(() => {
    dialog = jasmine.createSpyObj<MatDialog>('MatDialog', ['open']);
    TestBed.configureTestingModule({ providers: [{ provide: MatDialog, useValue: dialog }] });
    service = TestBed.inject(ConfirmDialogService);
  });

  it('opens the dialog with common.* defaults', () => {
    closingWith(true);

    service.confirm({ messageKey: 'a.message' }).subscribe();

    expect(dialog.open).toHaveBeenCalledWith(ConfirmDialogComponent, {
      data: {
        titleKey: 'common.confirm.title',
        messageKey: 'a.message',
        okKey: 'common.confirm.ok',
        cancelKey: 'common.confirm.cancel',
        params: {},
      },
      disableClose: true,
    });
  });

  it('lets the caller override the keys', () => {
    closingWith(true);

    service.confirm({ messageKey: 'm', titleKey: 't', okKey: 'o', cancelKey: 'c', params: { n: 1 } }).subscribe();

    expect(dialog.open.calls.mostRecent().args[1]!.data).toEqual({
      messageKey: 'm',
      titleKey: 't',
      okKey: 'o',
      cancelKey: 'c',
      params: { n: 1 },
    });
  });

  it('emits true only when the user accepts', () => {
    const results: boolean[] = [];
    closingWith(true);
    service.confirm({ messageKey: 'm' }).subscribe((r) => results.push(r));
    closingWith(false);
    service.confirm({ messageKey: 'm' }).subscribe((r) => results.push(r));
    closingWith(undefined);
    service.confirm({ messageKey: 'm' }).subscribe((r) => results.push(r));

    expect(results).toEqual([true, false, false]);
  });

  it('closes the dialog when unsubscribed before answering', () => {
    const ref = { afterClosed: () => NEVER, close: jasmine.createSpy('close') };
    dialog.open.and.returnValue(ref as any);

    service.confirm({ messageKey: 'm' }).subscribe().unsubscribe();

    expect(ref.close).toHaveBeenCalled();
  });
});
